        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02x: %s\n",
                MLX90614_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("MLX90614 detected at 0x%02x on %s. Reading every 5 seconds.\n",
           MLX90614_ADDR, I2C_BUS);

    while (running) {
        if (i2c_read_bytes(fd, buf, 2) == 0) {
            printf("MLX90614: 0x%02x 0x%02x\n", buf[0], buf[1]);
        } else {
            fprintf(stderr, "Failed to read MLX90614 data.\n");
        }
        sleep(5);
    }

    printf("\nExiting gracefully...\n");
