#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    uint8_t reg = ADS1115_ADDR;
    uint8_t buf[2];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        if (i2c_write_byte(fd, reg, 0x00) < 0) {
            fprintf(stderr, "Failed to start conversion: %s\n", strerror(errno));
            break;
        }
        usleep(10000); /* 10 ms conversion time */

        if (i2c_read_bytes(fd, reg, buf, 2) < 0) {
            fprintf(stderr, "Failed to read conversion result: %s\n", strerror(errno));
            break;
        }

        printf("ADS1115: Reg=0x%02X, Result=0x%02X\n", reg, buf[0]);
        fflush(stdout);

        usleep(100000); /* 100 ms between readings */
    }

    if (fd >= 0) {
        close(fd);
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define GPIO_LINE_18 18

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int setup_gpio(void) {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        chip = NULL;
        line = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Digital output control started on GPIO %d and GPIO %d.\n",
           GPIO_LINE, GPIO_LINE_18);
    printf("Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        if (val == 0) {
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("gpiod_line_set_value");
                cleanup_gpio();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: ON\n", GPIO_LINE);
        } else {
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("gpiod_line_set_value");
                cleanup_gpio();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: OFF\n", GPIO_LINE);
        }

        usleep(100000);
    }

    cleanup_gpio();
    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return 1;
    }

    while (program_running) {
        if (gpioPWM(PWM_PIN, PWM_RANGE) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", PWM_PIN);
            break;
        }
        gpioDelay(500000); /* 500 ms */
    }

    gpioPWM(PWM_PIN, 0); /* Turn off PWM */
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SOUND_PIN 17
#define ECHO_PIN 27
#define CHIP_NAME "gpiochip0"
#define POLL_INTERVAL_SEC 60

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *echo = gpiod_chip_get_line(chip, pin);
    if (!echo) {
        perror("gpiod_chip_get_line");
        return -1;
    }
    if (gpiod_line_request_output(echo, "hc-sr04", 0) < 0) {
        perror("gpiod_line_request_output");
        return -1;
    }
    return 0;
}

static int read_distance(struct gpiod_line *echo) {
    int val = gpiod_line_get_value(echo);
    if (val < 0) {
        perror("gpiod_line_get_value");
        return -1;
    }
    return val;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    sound_line = gpiod_chip_get_line(chip, SOUND_PIN);
    if (!sound_line) {
        perror("gpiod_chip_get_line (sound)");
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line (echo)");
        goto cleanup;
    }

    if (init_gpio(chip, SOUND_PIN) < 0 || init_gpio(chip, ECHO_PIN) < 0) {
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started on GPIO %d (echo), %d (sound). Press Ctrl+C to exit.\n",
           SOUND_PIN, ECHO_PIN);

    while (program_running) {
        int distance = read_distance(echo_line);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, exiting.\n");
            break;
        }

        if (distance > 400) {
            fprintf(stderr, "Distance out of range: %d cm\n", distance);
            break;
        }

        printf("Distance: %d cm\n", distance);
