        }
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (sound_line) gpiod_line_release(sound_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x28
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_ads1115(int fd) {
    if (i2c_write_reg(fd, ADS1115_REG_CONFIG, 0x8C) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg(fd, ADS1115_REG_CONFIG, 0x80) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg(fd, ADS1115_REG_CONFIG, 0x00) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_ads1115(int fd, int16_t *raw) {
    uint8_t buf[2];
    if (i2c_read_reg(fd, ADS1115_REG_CONVERSION, buf) < 0) return -1;
    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    if (init_ads1115(fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed.\n");
        goto cleanup;
    }

    printf("Starting ADS1115 sampling. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t raw;
        if (read_ads1115(fd, &raw) < 0) {
            fprintf(stderr, "Error reading ADS1115.\n");
            break;
        }

        if (raw < 0x8000) {
            fprintf(stderr, "Invalid ADS1115 reading: %d\n", raw);
            break;
        }

        printf("ADS1115: Raw=%d, Conversion=%d\n", raw, raw);
        fflush(stdout);

        usleep(5000000);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return ret;
}

