        usleep(CYCLE_DELAY_SEC * 1000000);

        /* Set output low */
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value low");
            break;
        }

        printf("Cycle %d complete\n", i + 1);
    }

    /* Cleanup */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}

