                break;
            }
        } else {
            /* Turn on the output */
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("gpiod_line_set_value(1)");
                break;
            }
        }

        printf("GPIO %d: %s\n", GPIO_LINE_OFFSET, value ? "ON" : "OFF");
        fflush(stdout);

        /* Sleep for the poll interval, checking for interrupt every second */
        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("\nExiting cleanly.\n");
    return ret;
}

