#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define SI7021_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_si7021(int fd, uint16_t *temp_c, uint16_t *hum_pct) {
    uint8_t buf[3];
    if (i2c_read_reg8(fd, 0x00, buf[0]) < 0) return -1;
    if (i2c_read_reg8(fd, 0x01, buf[1]) < 0) return -1;
    if (i2c_read_reg8(fd, 0x02, buf[2]) < 0) return -1;

    *temp_c = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *hum_pct = (uint16_t)buf[2];
    return 0;
}

int main(void) {
    int fd = -1;
    uint16_t temp_c = 0, hum_pct = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Starting SI7021 measurement. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_si7021(fd, &temp_c, &hum_pct) == 0) {
            printf("Temperature: %u C, Humidity: %u %%\n", temp_c, hum_pct);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    while (running) {
        uint8_t reg = 0x00;
        uint8_t buf[2];
        int ret = 0;

        if (i2c_write_byte(fd, reg, 0x00) < 0) {
            goto cleanup;
        }

        if (i2c_read_bytes(fd, reg, buf, 2) < 0) {
            goto cleanup;
        }

        int16_t adc_value = (buf[0] << 8) | buf[1];
        printf("ADC Value: %d\n", adc_value);
        fflush(stdout);

        usleep(1000 * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_OFFSET_1 8
#define GPIO_OFFSET_2 9
#define GPIO_OFFSET_3 10
#define GPIO_OFFSET_4 11
#define GPIO_OFFSET_5 23
#define GPIO_OFFSET_6 24

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[6] = {NULL, NULL, NULL, NULL, NULL, NULL};
static volatile int keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    int ret;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    for (int i = 0; i < 6; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_OFFSET_1 + i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_OFFSET_1 + i);
            cleanup_and_exit(0);
        }
    }

    /* Configure the lines as outputs, initially low */
    for (int i = 0; i < 6; i++) {
        ret = gpiod_line_request_output(lines[i], "digital-output", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output\n", GPIO_OFFSET_1 + i);
            cleanup_and_exit(0);
        }
    }

    /* Main loop: 256 cycles of 1s and 0s */
    for (int i = 0; i < 256 && keep_running; i++) {
        for (int j = 0; j < 6; j++) {
            if (gpiod_line_set_value(lines[j], 1) < 0) {
                fprintf(stderr, "Failed to set GPIO %d high\n", GPIO_OFFSET_1 + j);
                keep_running = 0;
                break;
            }
            usleep(1000000); /* 1 second */
        }
        for (int j = 0; j < 6; j++) {
            if (gpiod_line_set_value(lines[j], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %d low\n", GPIO_OFFSET_1 + j);
                keep_running = 0;
                break;
            }
            usleep(1000000); /* 1 second */
        }
    }

    /* Cleanup: release lines and close chip */
    for (int i = 0; i < 6; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Digital output control complete.\n");
    return EXIT_SUCCESS;
}

