static int setup_serial(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening serial port %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_serial(int fd, char *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        fprintf(stderr, "Error reading serial port: %s\n", strerror(errno));
        return -1;
    }
    return (int)n;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    char buffer[READ_SIZE];
    size_t buffer_size = 0;

    while (running) {
        int bytes_read = read_serial(fd, buffer, READ_SIZE);
        if (bytes_read < 0) {
            fprintf(stderr, "Error reading from serial port. Exiting.\n");
            break;
        }

        if (bytes_read == 0) {
            fprintf(stderr, "No data received from serial port.\n");
            break;
        }

        buffer_size += bytes_read;
        if (buffer_size >= READ_SIZE) {
            break;
        }

        size_t remaining = READ_SIZE - buffer_size;
        if (remaining > 0) {
            memmove(buffer, buffer + buffer_size, remaining);
            buffer_size = remaining;
        }

        printf("%s", buffer);
        fflush(stdout);
    }

    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

