#define DHT11_PIN 4
#define DHT11_CHIP_NAME "gpiochip4"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int dht11_init(struct gpiod_line *line)
{
    if (gpiod_line_request_input(line, DHT11_CHIP_NAME) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n",
                DHT11_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

static int dht11_read(struct gpiod_line *line, int *out_state)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Failed to read GPIO %d: %s\n",
                DHT11_PIN, strerror(errno));
        return -1;
    }
    *out_state = val;
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(DHT11_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", DHT11_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", DHT11_PIN, strerror(errno));
        goto cleanup;
    }

    if (dht11_init(line) < 0) {
        goto cleanup;
    }

    while (running) {
        int state;
        if (dht11_read(line, &state) < 0) {
            fprintf(stderr, "DHT11 read failed; retrying...\n");
            usleep(100000);
            continue;
        }

        if (state != DHT11_STATE_OK) {
            fprintf(stderr, "DHT11 read failed: %s\n",
                    (state == DHT11_STATE_ERROR) ? "ERROR" : "UNKNOWN");
            usleep(100000);
            continue;
        }

        printf("DHT11: state=0x%04X\n", state);
        fflush(stdout);

        usleep(50000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

