static void cleanup_gpio(void) {
    for (int i = 0; i < 10; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < 10; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", GPIO_OFFSET_1 + i);
                cleanup_gpio();
                return EXIT_FAILURE;
            }
            printf("GPIO %d set to 1\n", GPIO_OFFSET_1 + i);
        }
        for (int i = 0; i < 10 && keep_running; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", GPIO_OFFSET_1 + i);
                cleanup_gpio();
                return EXIT_FAILURE;
            }
            printf("GPIO %d set to 0\n", GPIO_OFFSET_1 + i);
        }
        usleep(100000);
    }

    printf("\nGPIO control stopped.\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

