        }

        /* Sleep for the requested interval, checking for signal */
        for (int ms = 0; ms < DELAY_MS && keep_running; ms += 10) {
            usleep(10 * 1000);
        }

        /* Turn off the output */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
    }

    /* Cleanup: turn off the output and release the line */
    gpiod_line_set_value(line, 1);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}

