#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/w1_bus.h>
#include <linux/w1_dev.h>

#define GPIO_1 4
#define GPIO_2 17
#define GPIO_3 18
#define GPIO_4 4
#define W1_BUS_NAME "/sys/bus/w1/devices"
#define W1_DEVICE_NAME "28-00XXXXXXXX"
#define W1_READ_FILE "/w1_bus/28-00XXXXXXXX/w1_slave"
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int w1_read_device(const char *device_path, char *buf, size_t len) {
    int fd = open(device_path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device_path, strerror(errno));
        return -1;
    }

    if (ioctl(fd, W1_GET_DEVICE_BUS, W1_DEVICE_NAME) < 0) {
        fprintf(stderr, "Error getting device bus: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, W1_GET_DEVICE_BUS, W1_DEVICE_NAME) < 0) {
        fprintf(stderr, "Error getting device bus: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, W1_GET_DEVICE_BUS, W1_DEVICE_NAME) < 0) {
        fprintf(stderr, "Error getting device bus: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading from %s: %s\n", device_path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static int w1_verify_device(const char *device_path) {
    char buf[32];
    if (w1_read_device(device_path, buf, sizeof(buf)) < 0) {
        return -1;
    }
    if (strncmp(buf, "28-00", 5) != 0) {
        return -1;
    }
    return 0;
}

static int w1_read_temperature(const char *device_path, float *temperature) {
    char buf[32];
    char cmd[32];
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "%s/%s/w1_slave", W1_BUS_NAME, W1_DEVICE_NAME);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (ioctl(fd, W1_GET_DEVICE_BUS, W1_DEVICE_NAME) < 0) {
        fprintf(stderr, "Error getting device bus: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, W1_GET_DEVICE_BUS, W1_DEVICE_NAME) < 0) {
        fprintf(stderr, "Error getting device bus: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, W1_GET_DEVICE_BUS, W1_DEVICE_NAME) < 0) {
        fprintf(stderr, "Error getting device bus: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);

    if (strncmp(buf, "YES", 3) != 0) {
        fprintf(stderr, "Invalid temperature reading from %s\n", path);
        return -1;
    }

    sscanf(buf, "%s", path);
    snprintf(cmd, sizeof(cmd), "cat %s | grep -o 'T=.*'", path);
    fd = open(cmd, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", cmd, strerror(errno));
        return -1;
    }

    char t_str[32];
    if (read(fd, t_str, sizeof(t_str)) < 0) {
        fprintf(stderr, "Error reading temperature from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);

    float temp = 0.0f;
    if (sscanf(t_str, "%f", &temp) == 1) {
        *temperature = temp;
    } else {
        fprintf(stderr, "Invalid temperature reading from %s\n", path);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    printf("Starting temperature monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (w1_verify_device(W1_DEVICE_NAME) < 0) {
            fprintf(stderr, "Device not found or invalid.\n");
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        if (w1_read_temperature(W1_DEVICE_NAME, &temperature) < 0) {
            fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        printf("Temperature: %.2f C\n", temperature);
        fflush(stdout);

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nExiting gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define HTU21D_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define READ_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read block failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int htu21d_init(int fd) {
    if (i2c_read_byte(fd, 0x00) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x01) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x02) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x03) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x04) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x05) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x06) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x07) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x08) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x09) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x0A) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x0B) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x0C) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x0D) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x0E) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    if (i2c_read_byte(fd, 0x0F) != 0x00) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        return -1;
    }
    return 0;
}

static int htu21d_read(int fd, uint16_t *out_temp, uint16_t *out_press) {
    uint8_t buf[3];
    if (i2c_read_block(fd, 0x10, buf, 3) != 0) {
        return -1;
    }
    *out_temp = (buf[0] << 8) | buf[1];
    *out_press = (buf[2] << 8) | 0x00;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (htu21d_init(fd) != 0) {
        fprintf(stderr, "HTU21D initialization failed.\n");
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t temp, press;
        if (htu21d_read(fd, &temp, &press) == 0) {
            printf("Temperature: %u C, Pressure: %u Pa\n", temp, press);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
