        }

        sleep(POLL_INTERVAL_SEC);
    }

    /* Cleanup */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    uint8_t reg = 0x2D;
    uint8_t buf[3];
    int ret;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        ret = i2c_read_bytes(fd, reg, buf, 3);
        if (ret < 0) {
            fprintf(stderr, "I2C read failed, continuing...\n");
            usleep(100000);
            continue;
        }

        // ADXL345 register map: 0x2D = 0x2D (default)
        // 0x2E = 0x00 (default)
        // 0x2F = 0x00 (default)
        // 0x30 = 0x00 (default)
        // 0x31 = 0x00 (default)
        // 0x32 = 0x00 (default)
        // 0x33 = 0x00 (default)
        // 0x34 = 0x00 (default)
        // 0x35 = 0x00 (default)
        // 0x36 = 0x00 (default)
        // 0x37 = 0x00 (default)
        // 0x38 = 0x00 (default)
        // 0x39 = 0x00 (default)
        // 0x3A = 0x00 (default)
        // 0x3B = 0x00 (default)
        // 0x3C = 0x00 (default)
        // 0x3D = 0x00 (default)
        // 0x3E = 0x00 (default)
        // 0x3F = 0x00 (default)

        printf("ADXL345: X=0x%02X, Y=0x%02X, Z=0x%02X\n", buf[0], buf[1], buf[2]);
        fflush(stdout);

        usleep(100000);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27
#define NUM_CYCLES 50

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    cleanup();
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Digital output control started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_LINE);

    for (int i = 0; i < NUM_CYCLES && !(i & 1); i += 2) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value (high)");
            cleanup();
            return EXIT_FAILURE;
        }
        usleep(100000);
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value (low)");
            cleanup();
            return EXIT_FAILURE;
        }
        usleep(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
