    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *dht22_lines[4] = {NULL, NULL, NULL, NULL};
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 4/5) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the four DHT22 lines */
    dht22_lines[0] = gpiod_chip_get_line(chip, DHT22_GPIO_1);
    dht22_lines[1] = gpiod_chip_get_line(chip, DHT22_GPIO_2);
    dht22_lines[2] = gpiod_chip_get_line(chip, DHT22_GPIO_3);
    dht22_lines[3] = gpiod_chip_get_line(chip, DHT22_GPIO_4);
    if (!dht22_lines[0] || !dht22_lines[1] || !dht22_lines[2] || !dht22_lines[3]) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the lines as outputs, initially low */
    if (gpiod_line_request_output(dht22_lines[0], "dht22", 0) < 0 ||
        gpiod_line_request_output(dht22_lines[1], "dht22", 0) < 0 ||
        gpiod_line_request_output(dht22_lines[2], "dht22", 0) < 0 ||
        gpiod_line_request_output(dht22_lines[3], "dht22", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("DHT22 monitoring started on GPIOs %d, %d, %d, %d. Press Ctrl+C to exit.\n",
           DHT22_GPIO_1, DHT22_GPIO_2, DHT22_GPIO_3, DHT22_GPIO_4);

    while (program_running) {
        int dht22_state = gpiod_line_get_value(dht22_lines[0]);
        if (dht22_state < 0) {
            perror("gpiod_line_get_value(dht22_0)");
