            perror("gpiod_line_get_value(dht22_2)");
            goto cleanup;
        }

        dht22_state = gpiod_line_get_value(dht22_lines[3]);
        if (dht22_state < 0) {
            perror("gpiod_line_get_value(dht22_3)");
            goto cleanup;
        }

        printf("DHT22 State: %d %d %d %d\n",
               dht22_state,
               dht22_state,
               dht22_state,
               dht22_state);

        /* Sleep 2 seconds, checking program_running every 100 ms */
        for (int i = 0; i < 20 && program_running; i++) {
            usleep(100000);
        }
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (dht22_lines[0]) {
        gpiod_line_set_value(dht22_lines[0], 0);
        gpiod_line_release(dht22_lines[0]);
    }
    if (dht22_lines[1]) {
        gpiod_line_set_value(dht22_lines[1], 0);
        gpiod_line_release(dht22_lines[1]);
