    if (dht22_lines[3]) {
        gpiod_line_set_value(dht22_lines[3], 0);
        gpiod_line_release(dht22_lines[3]);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int value) {
    if (gpioPWM(pin, value) != 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", pin, value);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction failed\n");
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins && running; i++) {
        if (set_pwm(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to set PWM on pin %d\n", pins[i]);
            running = 0;
            break;
        }
    }

    if (running) {
        while (running) {
            int val1 = gpioPWM(PWM_PIN_1, 0);
            int val2 = gpioPWM(PWM_PIN_2, 0);
            int val3 = gpioPWM(PWM_PIN_3, 0);

            if (val1 != 0 || val2 != 0 || val3 != 0) {
                fprintf(stderr, "Error: gpioPWM failed\n");
                running = 0;
                break;
            }

            printf("PWM on pins %d, %d, %d applied\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);
            fflush(stdout);

            gpioDelay(500000); /* 0.5 seconds */
        }
    }

    /* Clean shutdown: release hardware, terminate pigpio */
    gpioTerminate();
    return EXIT_SUCCESS;
}

