            printf("Output: ON\n");
        } else {
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("gpiod_line_set_value");
                break;
            }
            printf("Output: OFF\n");
        }

        usleep(100000); /* 100 ms */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

