#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return 1;
    }

    while (program_running) {
        if (gpioPWM(PWM_PIN, PWM_RANGE) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", PWM_PIN);
            break;
        }
        gpioDelay(10000); /* 10 ms */
    }

    gpioPWM(PWM_PIN, 0); /* Turn off PWM */
    gpioTerminate();
    return 0;
}

