#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x39
#define TCS34725_REG_ID 0x00
#define TCS34725_REG_CONFIG 0x01
#define TCS34725_REG_DATA 0x02

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, TCS34725_REG_ID, &id) < 0) {
        fprintf(stderr, "Failed to read TCS34725 ID register.\n");
        return -1;
    }
    if (id != 0x4D) {
        fprintf(stderr, "TCS34725 ID mismatch: 0x%02X (expected 0x4D).\n", id);
        return -1;
    }

    if (i2c_write_reg8(fd, TCS34725_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Failed to configure TCS34725.\n");
        return -1;
    }
    return 0;
}

static int tcs34725_read_raw(int fd, uint16_t *raw) {
    uint8_t buf[2];
    if (i2c_read_reg8(fd, TCS34725_REG_DATA, buf) < 0) {
        return -1;
    }
    *raw = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main(void) {
    int fd = -1;
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n", TCS34725_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(fd);
        return 1;
    }

    printf("TCS34725 initialized. Reading every 0.2 seconds. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t raw;
        if (tcs34725_read_raw(fd, &raw) < 0) {
            fprintf(stderr, "Failed to read TCS34725 data.\n");
            break;
        }

        printf("TCS34725 Raw: 0x%04X\n", raw);
        fflush(stdout);

        usleep(200000);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

