#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/v4l2.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define FILENAME "image.jpg"
#define CAPTURE_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

static int v4l2_open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying cap: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (!(cap & VIDIOC_CAP_VIDEOIN)) {
        fprintf(stderr, "Device %s does not support video capture\n", device_name);
        close(fd);
        return -1;
    }
    return fd;
}

static int v4l2_capture_image(int fd, uint32_t *width, uint32_t *height) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    *width = buf.width;
    *height = buf.height;
    return 0;
}

static int v4l2_capture_image_raw(int fd, uint32_t *width, uint32_t *height) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    *width = buf.width;
    *height = buf.height;
    return 0;
}

static int save_image(const char *filename, uint32_t width, uint32_t height) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    unsigned char *data = malloc(width * height * 3);
    if (!data) {
        fprintf(stderr, "Error allocating memory: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    for (uint32_t y = 0; y < height; y++) {
        for (uint32_t x = 0; x < width; x++) {
            uint32_t pixel = (x + y) * 3;
            data[pixel] = (uint8_t)((width - x) * (height - y) * 3);
            data[pixel + 1] = (uint8_t)((width - x) * (height - y) * 3 + 1);
            data[pixel + 2] = (uint8_t)((width - x) * (height - y) * 3 + 2);
        }
    }

    if (fwrite(data, 1, width * height * 3, fp) != (size_t)width * height * 3) {
        fprintf(stderr, "Error writing to %s: %s\n", filename, strerror(errno));
        free(data);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", filename, strerror(errno));
        free(data);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = v4l2_open_device(DEVICE_NAME);
    if (fd < 0) {
        return 1;
    }

    uint32_t width, height;
    if (v4l2_capture_image(fd, &width, &height) < 0) {
        close(fd);
        return 1;
    }

    printf("Captured image: %ux%u\n", width, height);

    if (save_image(FILENAME, width, height) < 0) {
        close(fd);
        return 1;
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 22
#define GPIO_LINE_OFFSET 27
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for line_offset (BCM numbering) */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started on GPIO %d and %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, GPIO_LINE_OFFSET + 1);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (value == 0) {
            printf("GPIO %d is LOW\n", GPIO_LINE_OFFSET);
        } else {
            printf("GPIO %d is HIGH\n", GPIO_LINE_OFFSET);
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Cleanup */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}

