#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg write");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg read");
        return -1;
    }
    return 0;
}

static int ads1115_init(int fd)
{
    if (i2c_write_reg(fd, ADS1115_REG_CONFIG, 0x80) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    if (ads1115_init(fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        goto cleanup;
    }

    printf("ADS1115 initialized at 0x%02X on %s\n", ADS1115_ADDR, I2C_BUS);

    while (g_running) {
        uint8_t config;
        if (i2c_read_reg(fd, ADS1115_REG_CONFIG, &config) < 0) {
            fprintf(stderr, "Failed to read ADS1115 config\n");
            break;
        }

        if (config & 0x01) {
            printf("ADS1115 error: conversion in progress\n");
            break;
        }

        int16_t raw;
        if (i2c_read_reg(fd, ADS1115_REG_CONV, &raw) < 0) {
            fprintf(stderr, "Failed to read ADS1115 conversion\n");
            break;
        }

        printf("ADS1115: %d\n", raw);
        fflush(stdout);

        usleep(200000);
    }

    printf("\nExiting cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
