#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("MPU6050 at 0x%02X on %s\n", MPU6050_ADDR, I2C_BUS);

    while (running) {
        uint8_t buf[6];
        if (i2c_read_bytes(fd, 0x00, buf, 6) < 0) {
            fprintf(stderr, "Failed to read 6 bytes from MPU6050\n");
            break;
        }

        int16_t ax, ay, az, gx, gy, gz;
        uint8_t xl, xh, yl, yh, zl, zh;

        ax = (int16_t)((buf[0] << 8) | buf[1]);
        ay = (int16_t)((buf[2] << 8) | buf[3]);
        az = (int16_t)((buf[4] << 8) | buf[5]);
        gx = (int16_t)((buf[6] << 8) | buf[7]);
        gy = (int16_t)((buf[8] << 8) | buf[9]);
        gz = (int16_t)((buf[10] << 8) | buf[11]);

        printf("Ax=%d, Ay=%d, Az=%d, Gx=%d, Gy=%d, Gz=%d\n", ax, ay, az, gx, gy, gz);
        fflush(stdout);

        usleep(10000);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

