#define MQTT_BROKER_HOST "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "rpi_sensor_reader"
#define MQTT_QOS 1
#define MQTT_RETAIN 0
#define MQTT_KEEPALIVE_INTERVAL 60
#define MQTT_RECONNECT_DELAY_MS 1000
#define MQTT_MAX_RECONNECT_ATTEMPTS 10
#define MQTT_MAX_PACKET_LEN 4096
#define MQTT_MAX_TOPIC_LEN 64
#define MQTT_MAX_PAYLOAD_LEN 1024
#define MQTT_MAX_TOPIC_LEN_EXTRA 64
#define MQTT_MAX_PAYLOAD_LEN_EXTRA 1024

static volatile sig_atomic_t g_running = 1;
static int g_mqtt_handle = -1;
static int g_mqtt_connected = 0;
static int g_mqtt_reconnect_attempts = 0;
static int g_mqtt_reconnect_delay_ms = MQTT_RECONNECT_DELAY_MS;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int mqtt_connect(void) {
    int rc;
    int attempt = 0;

    while (attempt < MQTT_MAX_RECONNECT_ATTEMPTS) {
        rc = mqtt_connect_with_retry(g_mqtt_broker_host, g_mqtt_broker_port, MQTT_CLIENT_ID, MQTT_QOS, MQTT_RETAIN, MQTT_KEEPALIVE_INTERVAL, MQTT_MAX_RECONNECT_ATTEMPTS, MQTT_MAX_PAYLOAD_LEN, MQTT_MAX_PAYLOAD_LEN_EXTRA, MQTT_MAX_TOPIC_LEN_EXTRA, MQTT_MAX_TOPIC_LEN, MQTT_MAX_PAYLOAD_LEN_EXTRA, MQTT_MAX_PAYLOAD_LEN);
        if (rc == 0) {
            g_mqtt_connected = 1;
            g_mqtt_reconnect_attempts = 0;
            return 0;
        }
        g_mqtt_reconnect_attempts++;
        if (g_mqtt_reconnect_attempts < MQTT_MAX_RECONNECT_ATTEMPTS) {
            gpioDelay(MQTT_RECONNECT_DELAY_MS * 1000);
        }
    }
    fprintf(stderr, "MQTT connection failed after %d attempts.\n", MQTT_MAX_RECONNECT_ATTEMPTS);
    return -1;
}

static int mqtt_publish(const char *topic, const char *payload, int qos) {
    int rc;
    int packet_len = MQTT_MAX_TOPIC_LEN + MQTT_MAX_PAYLOAD_LEN;
    char *packet = malloc(packet_len);
    if (!packet) {
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    if (mqtt_generate_packet(packet, &packet_len, topic, payload, qos) != 0) {
        free(packet);
        return -1;
    }

    rc = mqtt_publish_packet(g_mqtt_handle, packet, packet_len, qos);
    free(packet);
    return rc;
}

static void *mqtt_thread(void *arg) {
    (void)arg;
    while (g_running) {
        if (mqtt_connect() != 0) {
            gpioDelay(1000);
            continue;
        }
        if (mqtt_publish(MQTT_TOPIC, "sensor_data", MQTT_QOS) != 0) {
            gpioDelay(1000);
        }
        gpioDelay(MQTT_KEEPALIVE_INTERVAL * 1000);
    }
    g_mqtt_connected = 0;
    g_mqtt_reconnect_attempts = 0;
    mqtt_disconnect(g_mqtt_handle);
    g_mqtt_handle = -1;
    g_mqtt_connected = 0;
    return NULL;
}

