static int read_distance(struct gpiod_line *line, float *distance_cm) {
    int retries = 0;
    int valid = 0;

    while (retries < MAX_RETRIES) {
        int level = gpiod_line_get_value(line);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n",
                    SOUND_PIN_1, strerror(errno));
            return -1;
        }
        if (level == 0) {
            *distance_cm = (float)SOUND_PIN_1 / 2.0;
