            break;
        }
        if (level == 1) {
            *distance_cm = (float)SOUND_PIN_2 / 2.0;
            valid = 1;
            break;
        }
        if (level == 2) {
            *distance_cm = (float)SOUND_PIN_3 / 2.0;
            valid = 1;
            break;
        }
        usleep(10000);
        retries++;
    }

    if (!valid) {
        fprintf(stderr, "HC-SR04 not responding on GPIO %d\n", SOUND_PIN_1);
        return -1;
    }
    return 0;
}

