#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_23 23
#define GPIO_PIN_24 24
#define SOUND_SPEED_CM_PER_US 0.0343f
#define SOUND_DURATION_US 100000
#define POLL_INTERVAL_US 2000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("gpiod_chip_get_line");
        return -1;
    }
    if (gpiod_line_request_output(line, "hc-sr04", 0) < 0) {
        perror("gpiod_line_request_output");
        return -1;
    }
    return 0;
}

static int measure_distance(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value HIGH");
        return -1;
    }
    usleep(SOUND_DURATION_US);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value LOW");
        return -1;
    }
    usleep(SOUND_DURATION_US);
    return (int)((gpiod_line_get_value(line) * 1000000) / 2);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_23 = NULL, *line_24 = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line_23 = gpiod_chip_get_line(chip, GPIO_PIN_23);
    if (!line_23) {
        perror("gpiod_chip_get_line 23");
        goto cleanup;
    }
    line_24 = gpiod_chip_get_line(chip, GPIO_PIN_24);
    if (!line_24) {
        perror("gpiod_chip_get_line 24");
        goto cleanup;
    }

    if (init_gpio(chip, GPIO_PIN_23) < 0 || init_gpio(chip, GPIO_PIN_24) < 0) {
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started on GPIO %d and %d.\n", GPIO_PIN_23, GPIO_PIN_24);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        int distance = measure_distance(line_23);
        if (distance < 0) {
            fprintf(stderr, "Error measuring distance.\n");
            break;
        }

        if (distance > 0) {
            printf("Distance: %d cm\n", distance);
        } else {
            fprintf(stderr, "Invalid distance reading.\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line_23) gpiod_line_release(line_23);
    if (line_24) gpiod_line_release(line_24);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

