#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    for (int i = 0; i < 4 && program_running; i++) {
        int pwm_pins[4] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
        int values[4] = {0, 0, 0, 0};
        int pwm_pin = pwm_pins[i];

        for (int j = 0; j < 4 && program_running; j++) {
            if (gpioPWM(pwm_pin, values[j]) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on pin %d.\n", pwm_pin);
                break;
            }
            gpioDelay(10000); /* 10 ms */
        }
        if (program_running) {
            break;
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

