    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting cleanly.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_SIZE 1024

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main() {
    int fd = -1;
    struct termios tty;
    char buffer[READ_SIZE];
    int bytes_read = 0;

    // Set up signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open UART device
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART device %s: %s\n", UART_DEVICE, strerror(errno));
        return 1;
    }

    // Set serial port parameters
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error setting serial port attributes: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Set baud rate
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error setting baud rate: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    // Disable flow control
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;

    // Disable hardware flow control
    tty.c_cflag &= ~(CLOCAL | CREAD);

    // Set 8-bit data bits, no parity, 1 stop bit
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB);
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;

    // Disable XON/XOFF flow control
    tty.c_cflag &= ~(IXON | IXOFF | IXANY);

    // Set 8-bit input mode
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    // Set raw input mode
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    // Set input timeout
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1; // 1 second timeout

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (program_running) {
        // Read from UART
        if (read(fd, buffer, READ_SIZE) == 0) {
            bytes_read = read(fd, buffer, READ_SIZE);
            printf("%s", buffer);
        } else {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        }
        fflush(stdout);
    }

    // Cleanup
    if (fd >= 0) {
        tcflush(fd, TCIOFLUSH);
        close(fd);
    }

    return 0;
}

// Signal handler for graceful shutdown
void sig_handler(int signo) {
    (void)signo;
    program_running = 0;
}

