#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMstate(PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to set PWM state to 0 on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("PWM output on GPIO %d, frequency %d Hz, range %d.\n", PWM_PIN, PWM_FREQUENCY, PWM_RANGE);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        gpioPWM(PWM_PIN, PWM_RANGE);
        gpioDelay(100000); // 100ms delay
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM output stopped on GPIO %d.\n", PWM_PIN);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 5
#define GPIO_PIN_2 6
#define GPIO_PIN_3 13

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_line *line3 = NULL;
static volatile int keep_running = 1;

void cleanup(int signum) {
    (void)signum;
    keep_running = 0;
}

int main() {
    if (signal(SIGINT, cleanup) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line1, "digital-output", 0) < 0 ||
        gpiod_line_request_output(line2, "digital-output", 0) < 0 ||
        gpiod_line_request_output(line3, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup(0);
        return EXIT_FAILURE;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);
        int val3 = gpiod_line_get_value(line3);

        if (val1 < 0 || val2 < 0 || val3 < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (val1 == 1 && val2 == 1 && val3 == 1) {
            printf("Digital output ON\n");
        } else if (val1 == 1 && val2 == 0 && val3 == 1) {
            printf("Digital output ON\n");
        } else if (val1 == 1 && val2 == 1 && val3 == 0) {
            printf("Digital output ON\n");
        } else if (val1 == 0 && val2 == 1 && val3 == 1) {
            printf("Digital output ON\n");
        } else if (val1 == 0 && val2 == 0 && val3 == 1) {
            printf("Digital output ON\n");
        } else if (val1 == 0 && val2 == 1 && val3 == 0) {
            printf("Digital output ON\n");
        } else if (val1 == 0 && val2 == 0 && val3 == 0) {
            printf("Digital output ON\n");
        } else {
            printf("Digital output OFF\n");
        }

        usleep(100000);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>
#include <mqtt.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "rpi_sensor_client"
#define MQTT_QOS 1
#define MQTT_KEEPALIVE_INTERVAL 60
#define MQTT_MAX_PACKET_LEN 256

static volatile sig_atomic_t running = 1;
static int mqtt_client = -1;
static pthread_mutex_t mqtt_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mqtt_connect(void) {
    mqtt_client = mqtt_client_new(MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, MQTT_QOS, MQTT_KEEPALIVE_INTERVAL);
    if (mqtt_client == NULL) {
        fprintf(stderr, "Error: Failed to create MQTT client\n");
        return -1;
    }
    return 0;
}

static int mqtt_publish(const char *topic, const char *payload) {
    if (mqtt_client == NULL) {
        fprintf(stderr, "Error: MQTT client not connected\n");
        return -1;
    }
    if (mqtt_client_publish(mqtt_client, topic, payload, MQTT_QOS) != 0) {
        fprintf(stderr, "Error: Failed to publish to MQTT topic\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (mqtt_client != NULL) {
        mqtt_client_destroy(mqtt_client);
        mqtt_client = NULL;
    }
    gpioTerminate();
    pthread_mutex_destroy(&mqtt_mutex);
    printf("Cleanup complete. Exiting.\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (pthread_mutex_init(&mqtt_mutex, NULL) != 0) {
        fprintf(stderr, "Error: Failed to initialize mutex\n");
        gpioTerminate();
        return 1;
    }

    if (mqtt_connect() != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler\n");
    }

    printf("Sensor data publishing started. Press Ctrl+C to exit.\n");

    while (running) {
        char payload[MQTT_MAX_PACKET_LEN];
        snprintf(payload, sizeof(payload), "Sensor reading: %d", 123);

        if (mqtt_publish(MQTT_TOPIC, payload) != 0) {
            fprintf(stderr, "Error: Failed to publish sensor data\n");
        }

        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN1 2
#define PWM_PIN2 3
#define PWM_PIN3 18
#define PWM_PIN4 23
#define PWM_PIN5 24

static volatile int keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN1, 0);
    gpioPWM(PWM_PIN2, 0);
    gpioPWM(PWM_PIN3, 0);
    gpioPWM(PWM_PIN4, 0);
    gpioPWM(PWM_PIN5, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler.\n");
    }

    if (gpioSetMode(PWM_PIN1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN1);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN2);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN3);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN4);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN5, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN5);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN1, 100) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN1);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN2, 100) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN2);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN3, 100) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN3);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN4, 100) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN4);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN5, 100) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN5);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN1, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN1);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN2, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN2);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN3, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN3);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN4, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN4);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN5, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN5);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("PWM control started on GPIOs %d, %d, %d, %d, %d. Press Ctrl+C to exit.\n",
           PWM_PIN1, PWM_PIN2, PWM_PIN3, PWM_PIN4, PWM_PIN5);

    while (keep_running) {
        gpioPWM(PWM_PIN1, 1);
        gpioPWM(PWM_PIN2, 1);
        gpioPWM(PWM_PIN3, 1);
        gpioPWM(PWM_PIN4, 1);
        gpioPWM(PWM_PIN5, 1);
        gpioDelay(1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    gpioSetPWMfrequency(PWM_PIN_1, 100);
    gpioSetPWMfrequency(PWM_PIN_2, 100);
    gpioSetPWMfrequency(PWM_PIN_3, 100);

    gpioSetPWMrange(PWM_PIN_1, 255);
    gpioSetPWMrange(PWM_PIN_2, 255);
    gpioSetPWMrange(PWM_PIN_3, 255);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (program_running) {
        gpioPWM(PWM_PIN_1, 255);
        gpioPWM(PWM_PIN_2, 255);
        gpioPWM(PWM_PIN_3, 255);
        gpioDelay(100000); /* 100 ms */
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

