#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/v4l2-device.h>
#include <linux/v4l2-format.h>
#include <linux/v4l2-ctrl.h>
#include <linux/v4l2-pixformat.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define FILENAME "image.jpg"
#define CAPTURE_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int v4l2_open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying cap: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (!(cap & (1 << V4L2_CAP_VIDEO_CAPTURE))) {
        fprintf(stderr, "Device %s does not support video capture\n", device_name);
        close(fd);
        return -1;
    }
    return fd;
}

static int v4l2_set_format(int fd, V4L2_BUF_TYPE type, const V4L2_CAP_PARM *parm) {
    V4L2_BUF_TYPE type_val = (V4L2_BUF_TYPE)type;
    V4L2_CAP_PARM parm_val = parm;
    if (ioctl(fd, VIDIOC_S_BUF_TYPE, &type_val) < 0) {
        fprintf(stderr, "Error setting buffer type: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, VIDIOC_G_PARM, &parm_val) < 0) {
        fprintf(stderr, "Error getting parameter: %s\n", strerror(errno));
        return -1;
    }
    if (parm_val.type != type) {
        fprintf(stderr, "Error setting parameter type: %s (expected %s)\n",
                parm_val.type, type_val);
        return -1;
    }
    if (parm_val.value.s32 != type_val) {
        fprintf(stderr, "Error setting parameter value: %d (expected %d)\n",
                parm_val.value.s32, type_val);
        return -1;
    }
    return 0;
}

static int v4l2_set_format_auto(int fd) {
    V4L2_BUF_TYPE type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    V4L2_CAP_PARM parm = {0};
    parm.type = V4L2_CAP_VIDEO_CAPTURE;
    parm.value.s32 = 1;
    if (v4l2_set_format(fd, type, &parm) < 0) {
        return -1;
    }
    return 0;
}

static int v4l2_capture_image(int fd, const char *filename) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.index = 0;
    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }
    if (buf.length < 0) {
        fprintf(stderr, "Error capturing image: buffer length is negative\n");
        return -1;
    }
    if (buf.length > 0) {
        if (v4l2_capture_frame(fd, &buf) < 0) {
            fprintf(stderr, "Error capturing frame: %s\n", strerror(errno));
            return -1;
        }
    }
    if (v4l2_write_frame(fd, &buf) < 0) {
        fprintf(stderr, "Error writing frame: %s\n", strerror(errno));
        return -1;
    }
    if (v4l2_release_buffer(fd, &buf) < 0) {
        fprintf(stderr, "Error releasing buffer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int v4l2_write_frame(int fd, const V4L2_BUF_TYPE *buf) {
    if (ioctl(fd, VIDIOC_QBUF, buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = v4l2_open_device(DEVICE_NAME);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    if (v4l2_set_format_auto(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Capturing image... Press Ctrl+C to stop.\n");

    while (running) {
        if (v4l2_capture_image(fd, FILENAME) < 0) {
            fprintf(stderr, "Error capturing image, exiting.\n");
            break;
        }
        if (v4l2_write_frame(fd, NULL) < 0) {
            fprintf(stderr, "Error writing frame, exiting.\n");
            break;
        }
        usleep(CAPTURE_TIMEOUT_MS * 1000);
    }

    if (close(fd) < 0) {
