#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_SIZE 1024

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main() {
    int fd = -1;
    struct termios tty;
    char buffer[READ_SIZE];
    int bytes_read = 0;
    int bytes_written = 0;

    // Set up signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open UART device
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART device %s: %s\n", UART_DEVICE, strerror(errno));
        return 1;
    }

    // Set up termios options
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Set baud rate
    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting baud rate: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Set 8-bit data bits, no parity, 1 stop bit
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    // Set 8-bit data bits, no parity, 1 stop bit
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_iflag &= ~(IXANY | IXOFF | IXON);

    // Set 8-bit input
    tty.c_lflag = 0;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);

    // Set non-blocking
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1; // 1 second timeout

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Serial communication started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read from UART
        if (read(fd, buffer, READ_SIZE) == 0) {
            bytes_read = READ_SIZE;
            printf("Received: %s\n", buffer);
        } else if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // No data available
            usleep(10000);
            continue;
        } else {
            // Error reading
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            break;
        }

        // Write to UART
        if (write(fd, buffer, bytes_read) != bytes_written) {
            fprintf(stderr, "Error writing to UART: %s\n", strerror(errno));
            break;
        }
        bytes_written = bytes_written + bytes_written;
    }

    // Close UART
    if (fd >= 0) {
        close(fd);
    }

    printf("Serial communication stopped.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_18  18
#define GPIO_23  23
#define GPIO_24  24

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line18 = NULL, *line23 = NULL, *line24 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the default gpiochip (gpiochip0 on Pi 4/5, gpiochip0 on older) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line18 || !line23 || !line24) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request lines as outputs, initially LOW (digital output) */
    if (gpiod_line_request_output(line18, "digital-output", 0) < 0 ||
        gpiod_line_request_output(line23, "digital-output", 0) < 0 ||
        gpiod_line_request_output(line24, "digital-output", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as outputs: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (running) {
        int val18 = gpiod_line_get_value(line18);
        int val23 = gpiod_line_get_value(line23);
        int val24 = gpiod_line_get_value(line24);

        if (val18 < 0 || val23 < 0 || val24 < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            break;
        }

        printf("GPIO %d: %d\n", GPIO_18, val18);
        printf("GPIO %d: %d\n", GPIO_23, val23);
        printf("GPIO %d: %d\n", GPIO_24, val24);

        usleep(100000); /* 100 ms */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line18) gpiod_line_release(line18);
    if (line23) gpiod_line_release(line23);
    if (line24) gpiod_line_release(line24);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: Failed to set PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range to %d\n", PWM_RANGE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMstate(PWM_PIN, PI_HIGH) != 0) {
        fprintf(stderr, "Error: Failed to set PWM high state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("PWM output started on GPIO %d, frequency %d Hz, range %d\n",
           PWM_PIN, PWM_FREQUENCY, PWM_RANGE);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioPWM(PWM_PIN, PWM_RANGE) != 0) {
            fprintf(stderr, "Error: Failed to set PWM state\n");
            break;
        }
        gpioDelay(1000);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM output stopped.\n");
    return EXIT_SUCCESS;
}

