    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction failed\n");
    }

    if (setup_pwm(PWM_PIN_1) != 0 || setup_pwm(PWM_PIN_2) != 0 || setup_pwm(PWM_PIN_3) != 0) {
        fprintf(stderr, "Error: PWM setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

