            fprintf(stderr, "Error: gpioPWM(%d, 100) failed\n", PWM_PIN_3);
            break;
        }
        gpioDelay(500000);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_OFFSET_1   17
#define GPIO_OFFSET_2   23
#define GPIO_OFFSET_3   24
#define GPIO_OFFSET_4   25

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the four GPIO lines */
    lines[0] = gpiod_chip_get_line(chip, GPIO_OFFSET_1);
    lines[1] = gpiod_chip_get_line(chip, GPIO_OFFSET_2);
    lines[2] = gpiod_chip_get_line(chip, GPIO_OFFSET_3);
    lines[3] = gpiod_chip_get_line(chip, GPIO_OFFSET_4);
    if (!lines[0] || !lines[1] || !lines[2] || !lines[3]) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request each line as output, initially low */
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(lines[i], "digital-output", 0) < 0) {
            perror("gpiod_line_request_output");
            goto cleanup;
        }
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        /* Set the four lines to the desired values */
        if (gpiod_line_set_value(lines[0], 1) < 0) {
            perror("gpiod_line_set_value(0)");
            goto cleanup;
        }
        if (gpiod_line_set_value(lines[1], 1) < 0) {
            perror("gpiod_line_set_value(1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(lines[2], 1) < 0) {
            perror("gpiod_line_set_value(2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(lines[3], 1) < 0) {
            perror("gpiod_line_set_value(3)");
            goto cleanup;
        }

        /* Sleep for 10 seconds, checking for interrupt every 100 ms */
        for (int i = 0; i < 10 && program_running; i++) {
            usleep(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release the lines and close the chip */
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("\nDigital output control stopped.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>
#include <mqtt.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/mcp3008"
#define MCP3008_CHANNEL 0
#define MAX_VALUE 32767.0

static volatile sig_atomic_t running = 1;
static int mqtt_client = -1;
static pthread_mutex_t mqtt_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mqtt_connect(void) {
    mqtt_client = mqtt_client_new();
    if (!mqtt_client) {
        fprintf(stderr, "mqtt_client_new() failed\n");
        return -1;
    }

    mqtt_client_connect(mqtt_client, MQTT_BROKER, MQTT_PORT);
    if (!mqtt_client) {
        fprintf(stderr, "mqtt_client_connect() failed\n");
        mqtt_client_free(mqtt_client);
        mqtt_client = NULL;
        return -1;
    }

    return 0;
}

static int mqtt_publish(const char *topic, const char *payload) {
    if (!mqtt_client) {
        fprintf(stderr, "MQTT client not connected\n");
        return -1;
    }

    if (mqtt_client_publish(mqtt_client, topic, payload, 0) != 0) {
        fprintf(stderr, "MQTT publish failed\n");
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (gpioWrite(3, 1) < 0) {
        fprintf(stderr, "Failed to set MOSI high\n");
        return -1;
    }
    if (gpioWrite(4, 0) < 0) {
        fprintf(stderr, "Failed to set MISO low\n");
        gpioWrite(3, 0);
        return -1;
    }
    if (gpioWrite(5, 1) < 0) {
        fprintf(stderr, "Failed to set SCLK high\n");
        gpioWrite(3, 0);
        gpioWrite(4, 0);
        return -1;
    }
    if (gpioWrite(6, 0) < 0) {
        fprintf(stderr, "Failed to set SCLK low\n");
        gpioWrite(3, 0);
        gpioWrite(4, 0);
        gpioWrite(5, 0);
        return -1;
    }

    int adc_value = 0;
    for (int i = 0; i < 10; i++) {
        if (gpioWrite(3, 1) < 0) {
            fprintf(stderr, "Failed to set MOSI high\n");
            return -1;
        }
        if (gpioWrite(4, 1) < 0) {
            fprintf(stderr, "Failed to set MISO high\n");
            gpioWrite(3, 0);
            gpioWrite(4, 0);
            gpioWrite(5, 0);
            return -1;
        }
        if (gpioWrite(5, 0) < 0) {
            fprintf(stderr, "Failed to set SCLK low\n");
            gpioWrite(3, 0);
            gpioWrite(4, 0);
            gpioWrite(5, 0);
            return -1;
        }

        gpioDelay(1);

        if (gpioRead(3)) {
            adc_value = (adc_value << 1) | 1;
        } else {
            adc_value = (adc_value << 1) | 0;
        }

        if (gpioWrite(4, 1) < 0) {
            fprintf(stderr, "Failed to set MISO high\n");
            return -1;
        }
        if (gpioWrite(5, 0) < 0) {
            fprintf(stderr, "Failed to set SCLK low\n");
            gpioWrite(3, 0);
            gpioWrite(4, 0);
            return -1;
        }

        gpioDelay(1);
    }

    if (gpioWrite(3, 0) < 0) {
        fprintf(stderr, "Failed to set MOSI low\n");
        return -1;
    }
    if (gpioWrite(4, 0) < 0) {
        fprintf(stderr, "Failed to set MISO low\n");
        return -1;
    }
    if (gpioWrite(5, 0) < 0) {
        fprintf(stderr, "Failed to set SCLK low\n");
        return -1;
    }

    return (adc_value << 8) | rx[2];
}

static void *mcp3008_thread(void *arg) {
    (void)arg;
    int adc_value = -1;
    while (running) {
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read MCP3008\n");
            break;
        }
        if (adc_value > MAX_VALUE) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            break;
        }
        pthread_mutex_lock(&mqtt_mutex);
        if (mqtt_client) {
            char payload[64];
            snprintf(payload, sizeof(payload), "{\"value\": %.2f}", adc_value);
            if (mqtt_publish(MQTT_TOPIC, payload) != 0) {
                fprintf(stderr, "Failed to publish to MQTT\n");
            }
        }
        pthread_mutex_unlock(&mqtt_mutex);
        gpioDelay(10000);
    }
    return NULL;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (pthread_mutex_init(&mqtt_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex init failed\n");
        gpioTerminate();
        return 1;
    }

    if (mqtt_connect() != 0) {
        fprintf(stderr, "MQTT connection failed\n");
        pthread_mutex_destroy(&mqtt_mutex);
        gpioTerminate();
        return 1;
    }

    if (pthread_create(&mqtt_thread, NULL, mqtt_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create MQTT thread\n");
        mqtt_client_free(mqtt_client);
        mqtt_client = NULL;
        pthread_mutex_destroy(&mqtt_mutex);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
        } else {
            printf("ADC Value: %d\n", adc_value);
        }
        pthread_mutex_lock(&mqtt_mutex);
        if (mqtt_client) {
            char payload[64];
            snprintf(payload, sizeof(payload), "{\"value\": %.2f}", adc_value);
            if (mqtt_publish(MQTT_TOPIC, payload) != 0) {
                fprintf(stderr, "Failed to publish to MQTT\n");
            }
        }
        pthread_mutex_unlock(&mqtt_mutex);
        gpioDelay(100000);
    }

    if (mqtt_client) {
        mqtt_client_destroy(mqtt_client);
        mqtt_client = NULL;
    }
    pthread_mutex_destroy(&mqtt_mutex);
    gpioTerminate();
    return 0;
}

