#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define GPIO_LINE_18 18
#define NUM_CYCLES 3

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for line 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip again to get the line number */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for GPIO 18 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_18);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line for output, initially low */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    /* Main control loop */
    for (int i = 0; i < NUM_CYCLES && running; i++) {
        /* Set the output to the desired state */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        /* Sleep for 1 second (1000 ms) */
        usleep(1000);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        usleep(1000);
    }

    /* Cleanup: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}

