    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 0 (digital output) */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (val == 0) {
            printf("Digital output: OFF\n");
        } else {
            printf("Digital output: ON\n");
        }

        usleep(100000); /* 100 ms */
    }

    /* Cleanup */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}

