#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE_1 17
#define GPIO_LINE_2 18
#define GPIO_LINE_3 24

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_line *line3 = NULL;
static volatile sig_atomic_t keep_running = 1;

static void cleanup(void) {
    if (line1) { gpiod_line_release(line1); line1 = NULL; }
    if (line2) { gpiod_line_release(line2); line2 = NULL; }
    if (line3) { gpiod_line_release(line3); line3 = NULL; }
    if (chip) { gpiod_chip_close(chip); chip = NULL; }
}

static void sigint_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        perror("gpiod_chip_get_line (line 1)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line1, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output (line 1)");
        cleanup();
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        perror("gpiod_chip_get_line (line 2)");
