        perror("gpiod_line_request_output (line 2)");
        cleanup();
        return EXIT_FAILURE;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_LINE_3);
    if (!line3) {
        perror("gpiod_chip_get_line (line 3)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line3, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output (line 3)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val1 = gpiod_line_get_value(line1);
        if (val1 < 0) {
            perror("gpiod_line_get_value (line 1)");
            break;
        }
        int val2 = gpiod_line_get_value(line2);
        if (val2 < 0) {
