        printf("Line 1: %d, Line 2: %d, Line 3: %d\n", val1, val2, val3);

        if (val1 == 1) {
            if (gpiod_line_set_value(line1, 1) < 0) {
                perror("gpiod_line_set_value (line 1)");
                break;
            }
            if (gpiod_line_set_value(line2, 1) < 0) {
                perror("gpiod_line_set_value (line 2)");
                break;
            }
            if (gpiod_line_set_value(line3, 1) < 0) {
                perror("gpiod_line_set_value (line 3)");
                break;
            }
        } else if (val1 == 0) {
            if (gpiod_line_set_value(line1, 0) < 0) {
                perror("gpiod_line_set_value (line 1)");
                break;
            }
            if (gpiod_line_set_value(line2, 0) < 0) {
                perror("gpiod_line_set_value (line 2)");
                break;
            }
            if (gpiod_line_set_value(line3, 0) < 0) {
                perror("gpiod_line_set_value (line 3)");
                break;
            }
        } else {
            if (gpiod_line_set_value(line1, 1) < 0) {
                perror("gpiod_line_set_value (line 1)");
                break;
