                perror("gpiod_line_set_value (line 3)");
                break;
            }
        }

        usleep(10000);
    }

    cleanup();
    printf("Digital output control stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    int pwm_pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    int num_pins = sizeof(pwm_pins) / sizeof(pwm_pins[0]);

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetPWMfrequency(pwm_pins[i], 1000) != 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on pin %d.\n", pwm_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pwm_pins[i], 255) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on pin %d.\n", pwm_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pwm_pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to start PWM on pin %d.\n", pwm_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("PWM control started on GPIO %d, %d, %d, %d. Press Ctrl+C to exit.\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            int val = (running ? 1 : 0);
            if (gpioPWM(pwm_pins[i], val) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on pin %d.\n", pwm_pins[i]);
                cleanup();
                return EXIT_FAILURE;
            }
            printf("PWM %d: %d\n", pwm_pins[i], val);
        }
        sleep(1);
    }

    printf("\nExiting cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

