static int v4l2_open_device(const char *device_name)
{
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device_name, strerror(errno));
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap & VIDIOC_CAP_VIDEOIN)) {
        fprintf(stderr, "Device %s does not support video input.\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap & VIDIOC_CAP_OUTPUT)) {
        fprintf(stderr, "Device %s does not support output.\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap & VIDIOC_CAP_STREAMON)) {
        fprintf(stderr, "Device %s does not support streaming on.\n", device_name);
        close(fd);
        return -1;
    }

    return fd;
}

static int v4l2_open_device_with_retry(const char *device_name)
{
    int fd = -1;
    int attempts = 0;

    while (attempts < MAX_RETRIES) {
        fd = v4l2_open_device(device_name);
        if (fd >= 0)
            break;
        if (errno == EAGAIN)
            usleep(10000);
        else
            fprintf(stderr, "Error opening %s: %s\n", device_name, strerror(errno));
        attempts++;
    }

    if (fd < 0) {
        fprintf(stderr, "Failed to open %s after %d retries.\n", device_name, MAX_RETRIES);
        return -1;
    }

    return fd;
}

static int v4l2_set_format(int fd, const struct v4l2_capability *cap)
{
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = cap->capabilities.video_capabilities.width;
    fmt.fmt.pix.height = cap->capabilities.video_capabilities.height;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24;
    fmt.fmt.pix.sizeimage = cap->capabilities.video_capabilities.sizeimage;
    fmt.fmt.pix.mpeg_flags = 0;
    fmt.fmt.pix.colorspace = V4L2_COLOR_SPACE_RGB;
    fmt.fmt.pix.brightness = 0;
    fmt.fmt.pix.contrast = 0;
    fmt.fmt.pix.hue = 0;
    fmt.fmt.pix.vflip = 0;
    fmt.fmt.pix.userptr = 0;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int v4l2_start_capture(int fd)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    if (buf.index < 0 || buf.index >= buf.length) {
        fprintf(stderr, "Error: buffer index %d out of range\n", buf.index);
        return -1;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int v4l2_stop_capture(int fd)
{
    if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

