#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define PWM_DUTY_CYCLE 0.5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        int duty_cycle = (int)(PWM_DUTY_CYCLE * PWM_RANGE);
        if (gpioPWM(PWM_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Error: gpioPWM failed\n");
            break;
        }
        printf("PWM on GPIO %d, duty cycle: %d\n", PWM_PIN, duty_cycle);
        gpioDelay(5000000);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

