        perror("sigaction");
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

