#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 23
#define PWM_PIN_3 24

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int value) {
    if (gpioPWM(pin, value) != 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", pin, value);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins && running; i++) {
        if (set_pwm(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to set PWM on pin %d\n", pins[i]);
            break;
        }
    }

    if (running) {
        while (running) {
            int val1 = gpioPWM(PWM_PIN_1, 0);
            int val2 = gpioPWM(PWM_PIN_2, 0);
            int val3 = gpioPWM(PWM_PIN_3, 0);

            if (val1 != 0 || val2 != 0 || val3 != 0) {
                fprintf(stderr, "Error: gpioPWM failed\n");
                break;
            }

            printf("PWM set to %d %d %d\n", val1, val2, val3);
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown: release hardware, terminate pigpio */
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
