#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define SOUND_SPEED_CM_PER_US 0.0343f
#define TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("gpiod_chip_get_line");
        return -1;
    }
    if (gpiod_line_request_output(line, "hc-sr04", 0) < 0) {
        perror("gpiod_line_request_output");
        return -1;
    }
    return 0;
}

static int measure_distance(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value HIGH");
        return -1;
    }
    usleep(TIMEOUT_US);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value LOW");
        return -1;
    }
    usleep(TIMEOUT_US);
    int distance = (gpiod_line_get_value(line) == 0) ?
                    (int)((float)distance_in_cm * SOUND_SPEED_CM_PER_US) : -1;
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_17 = NULL, *line_18 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line_17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    line_18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line_17 || !line_18) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (init_gpio(chip, GPIO_PIN_17) < 0 || init_gpio(chip, GPIO_PIN_18) < 0) {
        goto cleanup;
    }

    printf("HC-SR04 ready on GPIO %d and GPIO %d.\n", GPIO_PIN_17, GPIO_PIN_18);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int distance = measure_distance(line_17);
        if (distance < 0) {
            fprintf(stderr, "Error: sensor not responding on GPIO %d.\n", GPIO_PIN_17);
            break;
        }
        if (distance < 0) {
            fprintf(stderr, "Error: sensor not responding on GPIO %d.\n", GPIO_PIN_18);
            break;
        }
        printf("Distance: %d cm\n", distance);
        fflush(stdout);
        usleep(100000);
    }

    printf("\nExiting...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line_17) gpiod_line_release(line_17);
    if (line_18) gpiod_line_release(line_18);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 23
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the line for BCM GPIO 23 */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (value == 0) {
            printf("GPIO %d: Low\n", GPIO_PIN);
        } else {
            printf("GPIO %d: High\n", GPIO_PIN);
        }

        usleep(POLL_INTERVAL_SEC * 1000000);
    }

    /* Cleanup: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_reg(fd, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg(fd, MPU6050_REG_PWR_MGMT_1, 0x01) < 0) return -1;
    usleep(100000);
    return 0;
}

static int read_accel_x(int fd, int16_t *x) {
    uint8_t buf[6];
    if (i2c_read_reg(fd, MPU6050_REG_ACCEL_XOUT_H, buf) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        int16_t ax, ay, az;
        if (read_accel_x(i2c_fd, &ax) < 0 || read_accel_x(i2c_fd, &ay) < 0 || read_accel_x(i2c_fd, &az) < 0) {
            fprintf(stderr, "Failed to read accelerometer data.\n");
            break;
        }
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", ax, ay, az);
        fflush(stdout);
        usleep(100000);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

