#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_OFFSET 5
#define NUM_GPIO_PIN 5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_GPIO_PIN];
static volatile int keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_GPIO_PIN; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_OFFSET + i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_OFFSET + i);
            cleanup_and_exit(0);
        }
        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_OFFSET + i);
            cleanup_and_exit(0);
        }
    }

    printf("GPIO output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < NUM_GPIO_PIN; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("gpiod_line_set_value");
                cleanup_and_exit(1);
            }
            printf("GPIO %d set to 1\n", GPIO_OFFSET + i);
        }
        sleep(1);

        for (int i = 0; i < NUM_GPIO_PIN; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("gpiod_line_set_value");
                cleanup_and_exit(1);
            }
            printf("GPIO %d set to 0\n", GPIO_OFFSET + i);
        }
        sleep(1);
    }

    cleanup_and_exit(0);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_OFFSET_1   17
#define GPIO_OFFSET_2   22
#define GPIO_OFFSET_3   27

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the three lines */
    line1 = gpiod_chip_get_line(chip, GPIO_OFFSET_1);
    line2 = gpiod_chip_get_line(chip, GPIO_OFFSET_2);
    line3 = gpiod_chip_get_line(chip, GPIO_OFFSET_3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request each line as output, initially low */
    if (gpiod_line_request_output(line1, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line3, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output(line3)");
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        /* Set the output values */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(line1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(line2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, 1) < 0) {
            perror("gpiod_line_set_value(line3)");
            goto cleanup;
        }

        /* Sleep 1 second */
        usleep(1000000);
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    /* Ensure all lines are released */
    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_set_value(line3, 0);

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_1);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_2);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_3);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_4);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, 1000) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN_1);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_2, 1000) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN_2);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_3, 1000) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN_3);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_4, 1000) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN_4);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN_1, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN_1);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_2, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN_2);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_3, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN_3);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_4, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN_4);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("PWM control started on GPIO %d, %d, %d, %d. Press Ctrl+C to exit.\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);

    while (running) {
        gpioPWM(PWM_PIN_1, 1);
        gpioPWM(PWM_PIN_2, 1);
        gpioPWM(PWM_PIN_3, 1);
        gpioPWM(PWM_PIN_4, 1);
        gpioDelay(1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

