#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 0 (digital output) */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (value == 0) {
            ret = gpiod_line_set_value(line, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                break;
            }
            printf("Output set to 1\n");
        } else {
            ret = gpiod_line_set_value(line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                break;
            }
            printf("Output set to 0\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Cleanup */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_OFFSET_1   2
#define GPIO_OFFSET_2   3
#define GPIO_OFFSET_5   5
#define GPIO_OFFSET_17  17

static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[5];
    int ret;

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the five GPIO lines */
    lines[0] = gpiod_chip_get_line(chip, GPIO_OFFSET_1);
    lines[1] = gpiod_chip_get_line(chip, GPIO_OFFSET_2);
    lines[2] = gpiod_chip_get_line(chip, GPIO_OFFSET_5);
    lines[3] = gpiod_chip_get_line(chip, GPIO_OFFSET_17);
    lines[4] = NULL; /* unused */

    if (!lines[0] || !lines[1] || !lines[2] || !lines[3] || !lines[4]) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request each line as output, initially low */
    ret = gpiod_line_request_output(lines[0], "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (offset 1)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(lines[1], "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (offset 2)");
        gpiod_line_release(lines[0]);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(lines[2], "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (offset 5)");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(lines[3], "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (offset 17)");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_line_release(lines[2]);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Set up signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_line_release(lines[2]);
        gpiod_line_release(lines[3]);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /*
         * Write 1 to all five lines to set the output to 1.
         * The libgpiod API does not support direct writes to multiple lines;
         * we must use a separate line for each bit.
         */
        for (int i = 0; i < 5; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("gpiod_line_set_value (write 1)");
                break;
            }
        }

        sleep(5);

        for (int i = 0; i < 5; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("gpiod_line_set_value (write 0)");
                break;
            }
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    for (int i = 0; i < 5; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

