#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/w1_bus.h>
#include <linux/w1_dev.h>

#define GPIO_PIN 4
#define W1_BUS_NAME "/dev/w1-bus0"
#define W1_DEVICE_NAME "/sys/bus/w1/devices/28-xxxxxx"
#define W1_DEVICE_ID_REG 0x00
#define W1_DEVICE_ID_VAL 0x28
#define W1_CONV_REG 0x01
#define W1_CONV_VAL 0x01
#define W1_RETRY_COUNT 3
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int w1_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int w1_init(void) {
    w1_fd = open(W1_DEVICE_NAME, O_RDWR);
    if (w1_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", W1_DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (ioctl(w1_fd, W1_DEVICE_ID, &W1_DEVICE_ID_VAL) < 0) {
        fprintf(stderr, "Error getting device ID: %s\n", strerror(errno));
        close(w1_fd);
        w1_fd = -1;
        return -1;
    }

    if (ioctl(w1_fd, W1_DEVICE_ID, &W1_DEVICE_ID_VAL) < 0) {
        fprintf(stderr, "Error getting device ID: %s\n", strerror(errno));
        close(w1_fd);
        w1_fd = -1;
        return -1;
    }

    if (ioctl(w1_fd, W1_CONV, &W1_CONV_VAL) < 0) {
        fprintf(stderr, "Error setting conversion value: %s\n", strerror(errno));
        close(w1_fd);
        w1_fd = -1;
        return -1;
    }

    return 0;
}

static int w1_read_temp(float *temp) {
    char buf[16];
    struct w1_bus_ioctl_data w1_data;
    int ret;

    memset(&w1_data, 0, sizeof(w1_data));
    w1_data.bus_type = W1_BUS_W1_GPIO;
    w1_data.device_path = W1_DEVICE_NAME;

    ret = ioctl(w1_fd, W1_BUS_IOCTL, &w1_data);
    if (ret < 0) {
        fprintf(stderr, "Error sending bus ioctl: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", W1_DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (ret > 0) {
        ret = read(w1_fd, buf, sizeof(buf));
        if (ret < 0) {
            fprintf(stderr, "Error reading from %s: %s\n", W1_DEVICE_NAME, strerror(errno));
            return -1;
        }
        if (ret == 0) {
            fprintf(stderr, "Error: No data received from %s\n", W1_DEVICE_NAME);
            return -1;
        }

        if (buf[0] & 0x01) {
            fprintf(stderr, "Error: DS18B20 not responding on %s\n", W1_DEVICE_NAME);
            return -1;
        }

        int raw = (buf[1] << 8) | buf[2];
        *temp = (raw - 128) / 10.0f;
        return 0;
    }

    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (w1_init() < 0) {
        return 1;
    }

    printf("Starting 1-Wire DS18B20 readings on GPIO %d...\n", GPIO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float temp;
        if (w1_read_temp(&temp) == 0) {
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nExiting gracefully...\n");
    if (w1_fd >= 0) {
        close(w1_fd);
        w1_fd = -1;
    }
    return 0;
}

