#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define ECHO_LINE   24

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE_CM  0.1
#define MAX_DISTANCE_CM  1000.0

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(struct gpiod_chip *chip, int trig_pin, int echo_pin, int echo_line) {
    struct gpiod_line *trig_line = gpiod_chip_get_line(chip, trig_pin);
    struct gpiod_line *echo_line = gpiod_chip_get_line(chip, echo_pin);
    if (!trig_line || !echo_line) {
        perror("gpiod_chip_get_line");
        return -1;
    }

    if (gpiod_line_request_output(trig_line, "hc-sr04-trigger", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        return -1;
    }
    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        return -1;
    }

    if (gpiod_line_request_output(echo_line, "hc-sr04-echo", 0) < 0) {
        perror("gpiod_line_request_output (echo)");
        return -1;
    }

    return 0;
}

static int measure_distance(struct gpiod_chip *chip, int trig_pin, int echo_pin, int echo_line) {
    if (gpiod_line_set_value(trig_line, 0) < 0) {
        perror("gpiod_line_set_value (trig)");
        return -1;
    }
    usleep(2);
    if (gpiod_line_set_value(trig_line, 1) < 0) {
        perror("gpiod_line_set_value (trig)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig_line, 0) < 0) {
        perror("gpiod_line_set_value (trig)");
        return -1;
    }

    int level = gpiod_line_get_value(echo_line);
    if (level < 0) {
        perror("gpiod_line_get_value (echo)");
        return -1;
    }

    if (level == 0) {
        return -1;  /* no echo */
    }

    int pulse_us = 0;
    int max_pulse = 100;  /* 100 us is ~2 cm */
    int min_pulse = 200;  /* 200 us is ~1 cm */

    while (pulse_us < max_pulse && pulse_us < max_pulse * 2 && pulse_us < max_pulse * 3 && pulse_us < max_pulse * 4) {
        if (gpiod_line_set_value(trig_line, 1) < 0) {
            perror("gpiod_line_set_value (trig)");
            return -1;
        }
        usleep(1);
        if (gpiod_line_set_value(trig_line, 0) < 0) {
            perror("gpiod_line_set_value (trig)");
            return -1;
        }
        usleep(1);
        pulse_us += 1;
    }

    if (pulse_us < min_pulse || pulse_us > max_pulse) {
        return -1;
    }

    int distance_cm = (pulse_us * SPEED_OF_SOUND) / 2 / 1000;
    return (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) ? -1 : distance_cm;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    int trig_pin = TRIGGER_PIN;
    int echo_pin = ECHO_PIN;
    int echo_line = ECHO_LINE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return 1;
    }

    if (setup_gpio(chip, trig_pin, echo_pin, echo_line) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = measure_distance(chip, trig_pin, echo_pin, echo_line);
        if (distance < 0) {
            fprintf(stderr, "Measurement failed, retrying...\n");
            usleep(100000);
            continue;
        }

        printf("Distance: %d cm\n", distance);
        fflush(stdout);

        usleep(100000);
    }

    printf("\nExiting...\n");
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

