#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8
#define NUM_CYCLES 3

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int setup_gpio(void) {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        chip = NULL;
        line = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high\n", GPIO_LINE);
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        printf("Cycles %d: GPIO %d set HIGH\n", i + 1, GPIO_LINE);
        usleep(100000);

        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d LOW\n", GPIO_LINE);
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        printf("Cycles %d: GPIO %d set LOW\n", i + 1, GPIO_LINE);
        usleep(100000);
    }

