#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_23 23
#define GPIO_PIN_24 24

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_17 = NULL;
static struct gpiod_line *line_23 = NULL;
static struct gpiod_line *line_24 = NULL;

static void cleanup(void) {
    if (line_17) {
        gpiod_line_release(line_17);
        line_17 = NULL;
    }
    if (line_23) {
        gpiod_line_release(line_23);
        line_23 = NULL;
    }
    if (line_24) {
        gpiod_line_release(line_24);
        line_24 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    int ret;

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get lines */
    line_17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line_17) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_PIN_17, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    line_23 = gpiod_chip_get_line(chip, GPIO_PIN_23);
    if (!line_23) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_PIN_23, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    line_24 = gpiod_chip_get_line(chip, GPIO_PIN_24);
    if (!line_24) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_PIN_24, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Request lines as outputs, initially low */
    ret = gpiod_line_request_output(line_17, "digital-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_PIN_17, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_23, "digital-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_PIN_23, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_24, "digital-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_PIN_24, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("Digital output control started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop: keep output low */
    while (1) {
        ret = gpiod_line_set_value(line_17, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_PIN_17, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        ret = gpiod_line_set_value(line_23, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_PIN_23, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        ret = gpiod_line_set_value(line_24, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_PIN_24, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        usleep(100000); /* 100 ms */
    }

    /* Should not reach here */
    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins && running; i++) {
        if (set_pwm(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to set PWM on pin %d\n", pins[i]);
            break;
        }
    }

    if (running) {
        while (running) {
            int duty_cycle = gpioRead(PWM_PIN_1);
            if (duty_cycle < 0) {
                fprintf(stderr, "Error: gpioRead failed on pin %d\n", PWM_PIN_1);
                break;
            }

            duty_cycle = gpioRead(PWM_PIN_2);
            if (duty_cycle < 0) {
                fprintf(stderr, "Error: gpioRead failed on pin %d\n", PWM_PIN_2);
                break;
            }

            duty_cycle = gpioRead(PWM_PIN_3);
            if (duty_cycle < 0) {
                fprintf(stderr, "Error: gpioRead failed on pin %d\n", PWM_PIN_3);
                break;
            }

            if (set_pwm(PWM_PIN_1, duty_cycle) != 0) {
                fprintf(stderr, "Error: failed to set PWM on pin %d\n", PWM_PIN_1);
                break;
            }

            if (set_pwm(PWM_PIN_2, duty_cycle) != 0) {
                fprintf(stderr, "Error: failed to set PWM on pin %d\n", PWM_PIN_2);
                break;
            }

            if (set_pwm(PWM_PIN_3, duty_cycle) != 0) {
                fprintf(stderr, "Error: failed to set PWM on pin %d\n", PWM_PIN_3);
                break;
            }

            printf("PWM applied: pin %d=%d, pin %d=%d, pin %d=%d\n",
                   PWM_PIN_1, duty_cycle,
                   PWM_PIN_2, duty_cycle,
                   PWM_PIN_3, duty_cycle);
            fflush(stdout);

            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown: release hardware on all exit paths */
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
