#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_OFFSET 8
#define NUM_GPIO 8

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_GPIO];
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int setup_gpio(void) {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }

    for (int i = 0; i < NUM_GPIO; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_OFFSET + i);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO %d\n", GPIO_OFFSET + i);
            return -1;
        }
    }

    for (int i = 0; i < NUM_GPIO; i++) {
        if (gpiod_line_request_output(lines[i], "digital-output", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO %d\n", GPIO_OFFSET + i);
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_GPIO; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < NUM_GPIO; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("gpiod_line_set_value (high)");
                cleanup_gpio();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: High\n", GPIO_OFFSET + i);
        }
        for (int i = 0; i < NUM_GPIO; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("gpiod_line_set_value (low)");
                cleanup_gpio();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: Low\n", GPIO_OFFSET + i);
        }
        usleep(100000);
    }

    cleanup_gpio();
    printf("Digital output control stopped.\n");
    return EXIT_SUCCESS;
}

