#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 4
#define GPIO_PIN_2 17
#define GPIO_PIN_3 18
#define CYCLES 5
#define DELAY_US 100000  /* 0.05 seconds */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the three GPIO lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "digital-output", 0) < 0 ||
        gpiod_line_request_output(line2, "digital-output", 0) < 0 ||
        gpiod_line_request_output(line3, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    for (int i = 0; i < CYCLES && running; i++) {
        /* Set line 1 high */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value (line 1)");
            goto cleanup;
        }
        usleep(DELAY_US);

        /* Set line 2 high */
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value (line 2)");
            goto cleanup;
        }
        usleep(DELAY_US);

        /* Set line 3 high */
        if (gpiod_line_set_value(line3, 1) < 0) {
            perror("gpiod_line_set_value (line 3)");
            goto cleanup;
        }
        usleep(DELAY_US);

        /* Set line 1 low */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value (line 1)");
            goto cleanup;
        }
        usleep(DELAY_US);

        /* Set line 2 low */
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value (line 2)");
            goto cleanup;
        }
        usleep(DELAY_US);

        /* Set line 3 low */
        if (gpiod_line_set_value(line3, 0) < 0) {
            perror("gpiod_line_set_value (line 3)");
            goto cleanup;
        }
        usleep(DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 17
#define GPIO_CHIP 0

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, 100) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, 255) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMstate(PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to set PWM state on GPIO %d to 0.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register signal handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM control started on GPIO %d. Press Ctrl+C to exit.\n", PWM_PIN);

    while (running) {
        if (gpioPWM(PWM_PIN, 100) != 0) {
            fprintf(stderr, "Error: Failed to set PWM state on GPIO %d to 100.\n", PWM_PIN);
            break;
        }
        time_sleep(0.1);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM control stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
