#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_OFFSETS   {4, 17, 22, 23, 24, 25, 27}
#define NUM_GPIO_CHIPS 1

static const unsigned int gpio_offsets[NUM_GPIO_CHIPS] = {4, 17, 22, 23, 24, 25, 27};
static const int num_gpio_pins = NUM_GPIO_CHIPS;

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int setup_gpio(struct gpiod_chip *chip, const unsigned int offsets[NUM_GPIO_CHIPS], int num_pins) {
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *line_settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_request_info *req_info = NULL;
    struct gpiod_request *req = NULL;
    int ret;

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n", strerror(errno));
        return -1;
    }

    line_settings = gpiod_line_settings_new();
    if (!line_settings) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        gpiod_line_config_free(line_cfg);
        return -1;
    }

    gpiod_line_settings_set_direction(line_settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(line_settings, GPIOD_LINE_VALUE_INACTIVE);

    line_cfg->consumer = "gpio-output-control";
    line_cfg->request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    line_cfg->flags = 0;

    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "gpiod_request_config_new failed: %s\n", strerror(errno));
        gpiod_line_config_free(line_cfg);
        return -1;
    }

    req_info = gpiod_request_info_new();
    if (!req_info) {
        fprintf(stderr, "gpiod_request_info_new failed: %s\n", strerror(errno));
        gpiod_request_config_free(req_cfg);
        gpiod_line_config_free(line_cfg);
        return -1;
    }

    gpiod_request_config_set_consumer(req_cfg, "gpio-output-control");
    gpiod_request_config_set_direction(req_cfg, GPIOD_REQUEST_DIRECTION_OUTPUT);
    gpiod_request_config_set_flags(req_cfg, 0);

    req = gpiod_chip_request_lines(chip, req_cfg, offsets, num_pins);
    if (!req) {
        fprintf(stderr, "gpiod_chip_request_lines failed: %s\n", strerror(errno));
        gpiod_request_config_free(req_cfg);
        gpiod_request_info_free(req_info);
        gpiod_line_config_free(line_cfg);
        return -1;
    }

    req_info->consumer = "gpio-output-control";
    req_info->request_type = GPIOD_REQUEST_DIRECTION_OUTPUT;
    req_info->flags = 0;

    req_cfg->consumer = "gpio-output-control";
    req_cfg->request_type = GPIOD_REQUEST_DIRECTION_OUTPUT;
    req_cfg->flags = 0;

    gpiod_request_config_free(req_cfg);
    gpiod_request_info_free(req_info);
    gpiod_line_config_free(line_cfg);

    return req;
}

static int set_gpio_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_request_info *req_info = NULL;
    struct gpiod_request *req = NULL;
    int ret = 1;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return 1;
    }

    for (int i = 0; i < NUM_GPIO_CHIPS; i++) {
        line = gpiod_chip_get_line(chip, gpio_offsets[i]);
        if (!line) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n", gpio_offsets[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(line, "gpio-output-control", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n", gpio_offsets[i], strerror(errno));
            goto cleanup;
        }
    }

    req = setup_gpio(chip, gpio_offsets, NUM_GPIO_CHIPS);
    if (req) {
        printf("GPIO control initialized successfully.\n");
    } else {
        fprintf(stderr, "GPIO initialization failed.\n");
        goto cleanup;
    }

    while (program_running) {
        int value = read_gpio_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO value. Exiting.\n");
