    if (gpioSetPWMfrequency(pin, 1000) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on pin %d\n", pin);
        return;
    }
    if (gpioPWM(pin, value) < 0) {
        fprintf(stderr, "Error: Failed to set PWM on pin %d\n", pin);
    }
