    for (int i = 0; i < 5 && program_running; i++) {
        set_pwm(PWM_PIN_1, 100);
        set_pwm(PWM_PIN_2, 100);
        set_pwm(PWM_PIN_3, 100);
        set_pwm(PWM_PIN_4, 100);

