#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN_1 4
#define DHT22_PIN_2 17
#define DHT22_CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int dht22_read(struct gpiod_line *line, int *out_val) {
    int val = 0;
    int retries = 3;
    int delay_us = 1000;

    while (retries > 0) {
        val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading DHT22 line: %s\n", strerror(errno));
            return -1;
        }
        if (val == 1) {
            *out_val = val;
            return 0;
        }
        usleep(delay_us);
        delay_us *= 2;
        retries--;
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *dht22_line1 = NULL;
    struct gpiod_line *dht22_line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(DHT22_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    dht22_line1 = gpiod_chip_get_line(chip, DHT22_PIN_1);
    if (!dht22_line1) {
        perror("gpiod_chip_get_line (DHT22_PIN_1)");
        goto cleanup;
    }

    dht22_line2 = gpiod_chip_get_line(chip, DHT22_PIN_2);
    if (!dht22_line2) {
        perror("gpiod_chip_get_line (DHT22_PIN_2)");
        goto cleanup;
    }

    if (gpiod_line_request_output(dht22_line1, "dht22-read", 0) < 0) {
        perror("gpiod_line_request_output (DHT22_PIN_1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(dht22_line2, "dht22-read", 0) < 0) {
        perror("gpiod_line_request_output (DHT22_PIN_2)");
        goto cleanup;
    }

    printf("DHT22 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int dht22_val1 = 0, dht22_val2 = 0;
        int ok1 = dht22_read(dht22_line1, &dht22_val1);
        int ok2 = dht22_read(dht22_line2, &dht22_val2);

        if (ok1 < 0 || ok2 < 0) {
            fprintf(stderr, "DHT22 read failed, exiting.\n");
            break;
        }

        if (ok1 == 0 || ok2 == 0) {
            fprintf(stderr, "DHT22 read failed after %d retries.\n", retries);
            break;
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char buf[64];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", t);

        printf("[%s] DHT22: Val1=0x%04X Val2=0x%04X\n", buf, dht22_val1, dht22_val2);

        sleep(60);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (dht22_line1) gpiod_line_release(dht22_line1);
    if (dht22_line2) gpiod_line_release(dht22_line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_OFFSET 8
#define NUM_GPIO_PINS 4

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_GPIO_PINS];
static volatile int keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    int ret;

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get lines */
    for (int i = 0; i < NUM_GPIO_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_OFFSET + i);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO %d\n", GPIO_OFFSET + i);
            cleanup_and_exit(0);
        }
    }

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    /* Configure lines as outputs, initially LOW */
    for (int i = 0; i < NUM_GPIO_PINS; i++) {
        ret = gpiod_line_request_output(lines[i], "gpio-output", 0);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO %d\n", GPIO_OFFSET + i);
            cleanup_and_exit(0);
        }
    }

    /* Main loop: one cycle every 1 second */
    while (keep_running) {
        for (int i = 0; i < NUM_GPIO_PINS; i++) {
            ret = gpiod_line_set_value(lines[i], 1);
            if (ret < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", GPIO_OFFSET + i);
                cleanup_and_exit(0);
            }
            printf("GPIO %d set to 1\n", GPIO_OFFSET + i);
        }
        sleep(1);

        ret = gpiod_line_set_value(lines[i], 0);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", GPIO_OFFSET + i);
            cleanup_and_exit(0);
        }
        printf("GPIO %d set to 0\n", GPIO_OFFSET + i);
    }

    /* Cleanup: turn off all outputs */
    for (int i = 0; i < NUM_GPIO_PINS; i++) {
        gpiod_line_set_value(lines[i], 0);
    }

    /* Close chip */
    gpiod_chip_close(chip);

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN_1, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_2, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN_2);
        gpioPWM(PWM_PIN_1, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_3, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN_3);
        gpioPWM(PWM_PIN_1, 0);
        gpioPWM(PWM_PIN_2, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM control started on GPIO %d, %d, %d. Press Ctrl+C to exit.\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);

    while (running) {
        if (gpioPWM(PWM_PIN_1, 1) != 0) {
            fprintf(stderr, "Error: PWM on GPIO %d failed.\n", PWM_PIN_1);
            break;
        }
        if (gpioPWM(PWM_PIN_2, 1) != 0) {
            fprintf(stderr, "Error: PWM on GPIO %d failed.\n", PWM_PIN_2);
            break;
        }
        if (gpioPWM(PWM_PIN_3, 1) != 0) {
            fprintf(stderr, "Error: PWM on GPIO %d failed.\n", PWM_PIN_3);
            break;
        }
        gpioDelay(1000000);
    }

    printf("\nExiting gracefully...\n");
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

