    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", BMP280_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("BMP280 ready. Press Ctrl+C to exit.\n");

    while (running) {
        float temp, press, hum;
        if (bmp280_read(fd, &temp, &press, &hum) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f hPa, Humidity: %.2f %%\n", temp, press, hum);
