            fprintf(stderr, "Error reading BMP280\n");
        }
        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return ret;
}

