#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (value == 0) {
            printf("Digital output: Low\n");
        } else {
            printf("Digital output: High\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    /* Cleanup */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define VEML7700_ADDR 0x10
#define I2C_DEV "/dev/i2c-1"
#define READ_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    int fd = -1;
    uint8_t reg = VEML7700_ADDR;
    uint16_t raw;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        if (i2c_read_reg8(fd, reg, &raw) == 0) {
            printf("VEML7700: 0x%02X = 0x%04X\n", reg, raw);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read VEML7700 register 0x%02X\n", reg);
        }
        usleep(READ_INTERVAL_US);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int setup_serial(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening serial port %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_serial(int fd, char *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        fprintf(stderr, "Error reading serial port: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) {
        return 0;
    }
    return (int)n;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = setup_serial(UART_DEVICE, BAUD_RATE);
    if (fd < 0) {
        return 1;
    }

    printf("Serial communication started. Press Ctrl+C to exit.\n");

    while (g_running) {
        char buf[256];
        ssize_t n = read_serial(fd, buf, sizeof(buf));
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error reading serial port: %s\n", strerror(errno));
            break;
        }
        if (n > 0) {
            printf("Received: %s\n", buf);
        }
        usleep(READ_INTERVAL_US);
    }

    if (close(fd) != 0) {
        fprintf(stderr, "Error closing serial port: %s\n", strerror(errno));
        return 1;
    }
    printf("Serial communication stopped.\n");
    return 0;
}

