#define ADXL345_ADDR 0x53
#define I2C_BUS "/dev/i2c-1"

static int i2c_fd = -1;

void cleanup(int signum) {
    (void)signum;
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized at 0x%02X on %s.\n", ADXL345_ADDR, I2C_BUS);

    while (1) {
        int16_t x, y, z;
        if (readI2CBlockData(i2c_fd, 0x41, (char *)&x, 3) < 0 ||
            readI2CBlockData(i2c_fd, 0x42, (char *)&y, 3) < 0 ||
            readI2CBlockData(i2c_fd, 0x43, (char *)&z, 3) < 0) {
            fprintf(stderr, "Failed to read ADXL345 data block: %s\n", strerror(errno));
            break;
        }

        printf("X: %4d, Y: %4d, Z: %4d\n", x, y, z);
        fflush(stdout);

        usleep(100000);
    }

    cleanup(0);
    return 0;
}

