#define GPIO_OFFSET_7 25
#define GPIO_OFFSET_8 27

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[8] = {NULL};
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_OFFSET_1 + i);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO %d\n", GPIO_OFFSET_1 + i);
            return -1;
        }
        if (gpiod_line_request_output(lines[i], "gpio-output", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO %d\n", GPIO_OFFSET_1 + i);
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("GPIO output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < 8; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", GPIO_OFFSET_1 + i);
                cleanup_gpio();
                return EXIT_FAILURE;
            }
            printf("GPIO %d set to 1\n", GPIO_OFFSET_1 + i);
        }
        usleep(100000);

        for (int i = 0; i < 8; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", GPIO_OFFSET_1 + i);
                cleanup_gpio();
                return EXIT_FAILURE;
            }
            printf("GPIO %d set to 0\n", GPIO_OFFSET_1 + i);
        }
        usleep(100000);
    }

    printf("\nGPIO output control stopped.\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

