#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 4
#define GPIO_LINE_CHANGE_EVENT 17
#define NUM_CYCLES 5

static struct gpiod_line *line = NULL;
static struct gpiod_chip *chip = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        chip = NULL;
        return 1;
    }

    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        chip = NULL;
        return 1;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    for (int i = 0; i < NUM_CYCLES && !(i % 2); i++) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        usleep(100000);
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        usleep(100000);
    }

    cleanup_and_exit(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define GPIO_LINE_OFFSET 21
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started on GPIO %d (BCM)\n", GPIO_LINE_OFFSET);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (value == 0) {
            printf("Digital output: LOW\n");
        } else {
            printf("Digital output: HIGH\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Cleanup */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}

