#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_OFFSET_1   17
#define GPIO_OFFSET_2   18
#define GPIO_OFFSET_3   22
#define GPIO_OFFSET_4   27

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    int ret;

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the four GPIO lines */
    lines[0] = gpiod_chip_get_line(chip, GPIO_OFFSET_1);
    lines[1] = gpiod_chip_get_line(chip, GPIO_OFFSET_2);
    lines[2] = gpiod_chip_get_line(chip, GPIO_OFFSET_3);
    lines[3] = gpiod_chip_get_line(chip, GPIO_OFFSET_4);

    if (!lines[0] || !lines[1] || !lines[2] || !lines[3]) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request each line as output, initially low */
    ret = gpiod_line_request_output(lines[0], "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (offset 1)");
        goto cleanup;
    }
    ret = gpiod_line_request_output(lines[1], "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (offset 2)");
        goto cleanup;
    }
    ret = gpiod_line_request_output(lines[2], "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (offset 3)");
        goto cleanup;
    }
    ret = gpiod_line_request_output(lines[3], "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (offset 4)");
        goto cleanup;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int val1 = gpiod_line_get_value(lines[0]);
        int val2 = gpiod_line_get_value(lines[1]);
        int val3 = gpiod_line_get_value(lines[2]);
        int val4 = gpiod_line_get_value(lines[3]);

        if (val1 < 0 || val2 < 0 || val3 < 0 || val4 < 0) {
            fprintf(stderr, "Error reading GPIO values.\n");
            break;
        }

        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               GPIO_OFFSET_1, val1,
               GPIO_OFFSET_2, val2,
               GPIO_OFFSET_3, val3,
               GPIO_OFFSET_4, val4);

        /* Sleep 0.5 seconds, checking program_running every 100 ms */
        for (int i = 0; i < 5 && program_running; i++) {
            usleep(100000);
        }
    }

cleanup:
    /* Release lines */
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    /* Close chip */
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nDigital output control stopped.\n");
    return (program_running) ? EXIT_SUCCESS : EXIT_FAILURE;
}

