}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define ECHO_THRESHOLD 100  // cm
#define MAX_DISTANCE_CM 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

    // Open the default gpiochip (gpiochip0 on Pi 4/5)
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Get the trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        goto cleanup;
    }

    // Request the trigger line as output, initially low
    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        goto cleanup;
    }

    // Get the echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        goto cleanup;
    }

    // Request the echo line as input
    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        perror("Failed to request echo line as input");
        goto cleanup;
    }

    // Set up signal handler for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            perror("Failed to set trigger high");
            goto cleanup;
        }
        usleep(10);  // 10 us trigger pulse
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            perror("Failed to set trigger low");
            goto cleanup;
        }

        // Wait for echo to go high (start of echo pulse)
        int timeout = 0;
        while (gpiod_line_get_value(echo_line) == 0) {
            if (++timeout > 100) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                break;
            }
            usleep(1);
        }
        if (timeout >= 100) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            break;
        }

        // Measure echo pulse duration
        int pulse_start = gpiod_line_get_value(echo_line);
        if (pulse_start < 0) {
            perror("Failed to read echo start");
            break;
        }
        int pulse_end = gpiod_line_get_value(echo_line);
        if (pulse_end < 0) {
            perror("Failed to read echo end");
            break;
        }

        // Calculate distance in cm
        int distance = (pulse_end - pulse_start) * 0.034 / 2;
        if (distance < 0 || distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Invalid distance: %d cm\n", distance);
            break;
        }

        printf("Distance: %d cm\n", distance);
        fflush(stdout);

        usleep(1000);  // 1 ms sampling interval
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

