        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMstate(PWM_PIN, PI_HIGH) != 0) {
        fprintf(stderr, "Error: Failed to set PWM state on GPIO %d to HIGH.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("PWM control started on GPIO %d. Press Ctrl+C to exit.\n", PWM_PIN);

    while (running) {
        if (gpioPWM(PWM_PIN, PWM_RANGE) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", PWM_PIN);
            break;
        }
        gpioDelay(1000);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM control stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define TCS34725_ADDR 0x29
#define I2C_BUS "/dev/i2c-1"
#define READ_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    int fd = -1;
    uint8_t reg = TCS34725_ADDR;
    uint16_t raw;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 at 0x%02X on %s\n", TCS34725_ADDR, I2C_BUS);

    while (running) {
        if (i2c_read_reg8(fd, reg, &raw) == 0) {
            printf("Raw: 0x%04X\n", raw);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read TCS34725 register 0x%02X\n", reg);
        }
        usleep(READ_INTERVAL_US);
    }

    printf("\nExiting cleanly.\n");
    if (fd >= 0) close(fd);
    return EXIT_SUCCESS;
}

