        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for line 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Open the GPIO line for input */
    line = gpiod_chip_get_line(chip, GPIO_LINE_18);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input */
    ret = gpiod_line_request_input(line, "digital-output");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        printf("Value: %d\n", val);

        if (val == 1) {
            ret = gpiod_line_set_value(line, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                break;
            }
        } else {
            ret = gpiod_line_set_value(line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                break;
            }
        }

        usleep(100000); /* 100 ms */
    }

    /* Cleanup */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_18  18
#define GPIO_23  23
#define GPIO_24  24

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line18 = NULL, *line23 = NULL, *line24 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the default gpiochip (gpiochip0 on Pi 4/5) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line18 || !line23 || !line24) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request the lines as outputs, initially low */
    if (gpiod_line_request_output(line18, "digital-output", 0) < 0 ||
        gpiod_line_request_output(line23, "digital-output", 0) < 0 ||
        gpiod_line_request_output(line24, "digital-output", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as outputs: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Main loop: report state every 0.1 seconds */
    while (running) {
        int val18 = gpiod_line_get_value(line18);
        int val23 = gpiod_line_get_value(line23);
        int val24 = gpiod_line_get_value(line24);

        if (val18 < 0 || val23 < 0 || val24 < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               GPIO_18, val18,
               GPIO_23, val23,
               GPIO_24, val24);

        usleep(100000); /* 100 ms */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines on exit */
    if (line18) gpiod_line_release(line18);
    if (line23) gpiod_line_release(line23);
    if (line24) gpiod_line_release(line24);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define I2C_DEV "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    uint8_t buf[6];
    int16_t ax, ay, az, gx, gy, gz;
    int ret;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        if (i2c_read_bytes(fd, 0x3B, buf, 6) == 0) {
            ax = (int16_t)((buf[0] << 8) | buf[1]);
            ay = (int16_t)((buf[2] << 8) | buf[3]);
            az = (int16_t)((buf[4] << 8) | buf[5]);
            gx = (int16_t)((buf[2] << 8) | buf[3]);
            gy = (int16_t)((buf[4] << 8) | buf[5]);
            gz = (int16_t)((buf[6] << 8) | buf[7]);

            printf("Ax=%d, Ay=%d, Az=%d, Gx=%d, Gy=%d, Gz=%d\n", ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read MPU6050 data\n");
        }

        sleep(1);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_MS 600

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (value == 0) {
            ret = gpiod_line_set_value(line, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                break;
            }
            printf("Output: ON\n");
        } else {
            ret = gpiod_line_set_value(line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                break;
            }
            printf("Output: OFF\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Cleanup */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nDigital output control stopped.\n");
    return EXIT_SUCCESS;
}
